     * Returns the gender of the animal.
     * 
     * @return Returns true if female.
     */
    protected boolean getIsFemale() 
    {
        return isFemale;
    }

    /**
     * @Override
     * 
     * Increase the age.
     * This could result in the Animal's death.
     */
    protected void incrementAge()
    {
        age++;
        if(age > maxAge) {
